const rawItems = $items('Convert RSS XML to JSON')[0]?.json?.rss?.channel?.item || [];
const rssItems = Array.isArray(rawItems) ? rawItems : (rawItems ? [rawItems] : []);
const publishedRows = $items('Get Already-Published Topics') || [];

// Stop words to strip
const STOP_WORDS = new Set([
  'the','a','an','and','for','in','of','to','why','what','how','is','are','on','at',
  'with','by','from','this','that','will','can','guide','update','news','2026','2025',
  'bengaluru','bangalore','karnataka','property','owner','owners','plots','plot','site','land'
]);

function getKeywords(text) {
  return (text || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !STOP_WORDS.has(w));
}

// Extract all published titles, slugs, and focus keywords
const publishedRecords = publishedRows.map(r => {
  const j = r.json || {};
  const titleWords = getKeywords(j.title || '');
  const slugWords = getKeywords((j.slug || '').replace(/-/g, ' '));
  const focusWords = getKeywords(j.focus_keyword || '');
  return {
    rawTitle: j.title || '',
    allWords: new Set([...titleWords, ...slugWords, ...focusWords])
  };
}).filter(p => p.allWords.size > 0);

const publishedTitleList = publishedRows.map(r => r.json?.title).filter(Boolean);

function isDuplicate(candidateText) {
  const candWords = getKeywords(candidateText);
  if (candWords.length === 0) return true;

  for (const pub of publishedRecords) {
    let matchCount = 0;
    for (const w of candWords) {
      if (pub.allWords.has(w)) matchCount++;
    }
    // If 35% or more core topic keywords overlap, treat as duplicate
    const overlapRatio = matchCount / Math.min(candWords.length, pub.allWords.size);
    if (overlapRatio >= 0.35 || matchCount >= 3) {
      return true;
    }
  }
  return false;
}

// 30+ Diverse, High-intent Bengaluru NRI Property Topics (rotates automatically)
const TOPIC_LIBRARY = [
  "BBMP e-Khata Mandatory Digitisation: How Outstation Owners Can Verify PID Online",
  "Preventing Encroachment on Vacant Plots in Bengaluru: RCC Compound Wall and Signage Guide",
  "BBMP Property Tax Amnesty OTS Scheme: Penalty Waivers for Absentee Landlords",
  "BMRDA and BDA Master Plan 2031 Zonal Clearances for Peripheral Bengaluru Sites",
  "Kaveri 2.0 Online Encumbrance Certificate (EC) Verification for Land in Karnataka",
  "Stormwater Drain (SWD) and Lake Buffer Zone Demolition Risks for Bengaluru Properties",
  "Managing Inherited Ancestral Land in Devanahalli and Sarjapur: Step-by-Step Security Protocol",
  "Gram Panchayat 11B Form Conversion to BBMP e-Khata in Outer Bengaluru Layouts",
  "High-Tension Power Line Setback Rules and Buffer Clearances for Residential Plots",
  "Agricultural Land Non-Agricultural (NA) DC Conversion Verification Guide for NRIs",
  "How to Check Land Survey Numbers and RTC Pahani Records on Karnataka Bhoomi Portal",
  "Preventing Fraudulent GPA and Fake Sale Deeds on Unoccupied Bengaluru Sites",
  "Bengaluru Sub-Registrar Guideline Values 2026: What Property Buyers Must Know",
  "Boundary Stone Marking & GPS Geotagging: Why Physical Verification Beats Satellite Maps",
  "BBMP Solid Waste Management Bye-Laws: Penalties for Unmaintained Vacant Plots in Bangalore"
];

// 1. Check RSS Feed first
for (const it of rssItems) {
  const fullTitle = it.title || '';
  const parts = fullTitle.split(' - ');
  const cleanTitle = parts.slice(0, -1).join(' - ').trim() || fullTitle.trim();

  if (!cleanTitle || cleanTitle.length < 15) continue;
  if (isDuplicate(cleanTitle)) continue;

  const snippet = (it.description || '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();

  return [{
    json: {
      title: cleanTitle,
      snippet: snippet,
      source: parts.length > 1 ? parts[parts.length - 1].trim() : 'Civic News',
      published_titles_to_avoid: publishedTitleList.slice(-10)
    }
  }];
}

// 2. If RSS is duplicate/stale, pick first unused from Topic Library
for (const topic of TOPIC_LIBRARY) {
  if (!isDuplicate(topic)) {
    return [{
      json: {
        title: topic,
        snippet: 'Comprehensive field guide, municipal bylaws, and prevention protocols for property owners in Bengaluru.',
        source: 'PropVigil Civic Research Desk',
        published_titles_to_avoid: publishedTitleList.slice(-10)
      }
    }];
  }
}

// 3. Guaranteed fresh unique angle with month/year
const currentMonthYear = new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
const dynamicTitle = `Bengaluru Vacant Land Security & Civic Notice Audit: ${currentMonthYear} Field Manual`;
return [{
  json: {
    title: dynamicTitle,
    snippet: 'Quarterly field inspection guide, boundary dispute prevention, and municipal tax compliance.',
    source: 'PropVigil Field Intelligence',
    published_titles_to_avoid: publishedTitleList.slice(-10)
  }
}];

