let raw = $json.choices?.[0]?.message?.content || '{}';

raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');
const cleaned = (firstBrace !== -1 && lastBrace !== -1)
  ? raw.slice(firstBrace, lastBrace + 1)
  : raw;

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse blog JSON: ' + e.message);
}

if (!parsed.slug) {
  parsed.slug = (parsed.title || 'bengaluru-property-guide')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');
}

return [{ json: parsed }];

const photos = $json.results || [];
const publishedRows = $items('Get Already-Published Topics') || [];

const publishedImageUrls = new Set(
  publishedRows.map(r => r.json.image_url || '').filter(Boolean)
);

const unusedPhotos = photos.filter(p => {
  const url = p.urls?.regular || p.urls?.full;
  return url && !publishedImageUrls.has(url);
});

const candidatePhotos = unusedPhotos.length > 0 ? unusedPhotos : photos;
let selected = candidatePhotos[Math.floor(Math.random() * candidatePhotos.length)];

const imageUrl = selected?.urls?.regular || "https://images.unsplash.com/photo-1560518883-ce09059eeffa?w=1200";
const imageAlt = selected?.alt_description || $('Parse Generated Blog JSON').item.json.image_alt_text || "Property inspection and vacant site monitoring in Bengaluru";

return [{ json: { image_url: imageUrl, image_alt_text: imageAlt } }];
